AHB.audio({"groups": {"part-01-vocabulary": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-01-vocabulary/001.mp3", "text": "Huda sends an (1)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-01-vocabulary/002.mp3", "text": "The (2)… is 45,000 dollars."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-01-vocabulary/003.mp3", "text": "The (3)… is the first of May."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-01-vocabulary/004.mp3", "text": "Ms. Chen makes a bank (4)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-01-vocabulary/005.mp3", "text": "The invoice is now (5)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-01-vocabulary/006.mp3", "text": "Huda writes it in the payments (6)"}], "title": "Read and listen"}], "part-02-grammar": [{"clips": [{"ar": "نستخدم الماضي البسيط لفعل منتهٍ في الماضي.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/001.mp3", "text": "We use the PAST SIMPLE for a finished action in the past."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/002.mp3", "text": "For REGULAR verbs, add -ed: check → checked, receive → received, arrive → arrived."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/003.mp3", "text": "We checked the invoice."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/004.mp3", "text": "The goods arrived yesterday."}, {"ar": "الماضي البسيط واحد لجميع الضمائر: أنا، وأنت، وهو، ونحن، وهم.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/005.mp3", "text": "The past simple is the same for all persons (I, you, he, we, they)."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/006.mp3", "text": "Some verbs are IRREGULAR — they do not add -ed."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/007.mp3", "text": "You must learn them: pay → paid, send → sent, make → made, get → got, buy → bought."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/008.mp3", "text": "Ms. Chen paid the invoice."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/009.mp3", "text": "Huda sent the invoice."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/010.mp3", "text": "She made a bank transfer."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/011.mp3", "text": "We use TIME EXPRESSIONS to say when: yesterday, last week, last month, two days ago, on Monday, in May."}, {"ar": "هذه الكلمات تخبرنا أن الفعل قد انتهى.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/012.mp3", "text": "These words tell us the action is finished."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/013.mp3", "text": "We sent it yesterday."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/014.mp3", "text": "She paid two days ago."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/015.mp3", "text": "The goods arrived last week."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/016.mp3", "text": "For QUESTIONS, use DID + verb (base form): Did you pay the invoice?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/017.mp3", "text": "When did they pay?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/018.mp3", "text": "For NEGATIVES, use DIDN'T + verb: They didn't pay yet."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/019.mp3", "text": "We didn't send the invoice."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/020.mp3", "text": "After 'did' and 'didn't', use the base verb, not the past: Did you PAY (NOT 'Did you paid')."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/021.mp3", "text": "After DID and DIDN'T, use the base verb: 'Did you pay?' and 'She didn't pay' (NOT 'Did you paid' or 'She didn't paid')."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-02-grammar/022.mp3", "text": "Learn the irregular verbs by heart: pay → paid, send → sent, make → made, get → got, buy → bought."}], "title": "Read and listen"}], "part-03-listening": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-03-listening/001.mp3", "text": "Listen and read. (Your teacher will read the dialogue, or play the audio.)"}], "title": "Read and listen"}, {"clips": [{"ar": "مرحباً يا هدى. دفعت الفاتورة أمس، بحوالة مصرفية.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-03-listening/002.mp3", "text": "Hello, Huda. I paid the invoice yesterday, by bank transfer."}, {"ar": "شكراً لك يا سيدة تشِن. دعيني أتحقق. نعم، استلمناها هذا الصباح.", "speaker": "Huda", "src": "../../assets/audio/unit-07/part-03-listening/003.mp3", "text": "Thank you, Ms. Chen. Let me check. Yes — we received it this morning."}, {"ar": "جيد. كم استلمتم؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-03-listening/004.mp3", "text": "Good. How much did you receive?"}, {"ar": "", "speaker": "Huda", "src": "../../assets/audio/unit-07/part-03-listening/005.mp3", "text": "45,000 dollars. That is the full amount. Your invoice is now paid."}, {"ar": "وحسابي؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-03-listening/006.mp3", "text": "And my account?"}, {"ar": "حسابك مسدّد. لا تدينين بشيء. شكراً لدفعك في الموعد.", "speaker": "Huda", "src": "../../assets/audio/unit-07/part-03-listening/007.mp3", "text": "Your account is clear. You owe nothing. Thank you for paying on time."}, {"ar": "بالطبع. نحن ندفع دائماً في الموعد. متى أرسلتِ الفاتورة؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-03-listening/008.mp3", "text": "Of course. We always pay on time. When did you send the invoice?"}, {"ar": "", "speaker": "Huda", "src": "../../assets/audio/unit-07/part-03-listening/009.mp3", "text": "I sent it two weeks ago. The due date was the first of May, and you paid before that."}, {"ar": "ممتاز. أتطلّع إلى طلبنا القادم.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-03-listening/010.mp3", "text": "Perfect. I look forward to our next order."}], "title": "Dialogue D1"}, {"clips": [{"ar": "", "speaker": "Huda", "src": "../../assets/audio/unit-07/part-03-listening/011.mp3", "text": "Hello. Did you pay invoice PO-1244?"}, {"ar": "ليس بعد. أعتذر. سأدفعها هذا الأسبوع.", "speaker": "Partner", "src": "../../assets/audio/unit-07/part-03-listening/012.mp3", "text": "Not yet. I am sorry. I am going to pay it this week."}, {"ar": "لا مشكلة. تاريخ الاستحقاق يوم الجمعة. هل يمكنك الدفع قبل الجمعة؟", "speaker": "Huda", "src": "../../assets/audio/unit-07/part-03-listening/013.mp3", "text": "No problem. The due date is Friday. Can you pay before Friday?"}, {"ar": "نعم، بالطبع. سأجري الحوالة يوم الأربعاء.", "speaker": "Partner", "src": "../../assets/audio/unit-07/part-03-listening/014.mp3", "text": "Yes, of course. I will make the transfer on Wednesday."}, {"ar": "شكراً لك. عندما تدفع، أرجو أن ترسل لي رسالة.", "speaker": "Huda", "src": "../../assets/audio/unit-07/part-03-listening/015.mp3", "text": "Thank you. When you pay, please send me a message."}, {"ar": "بالطبع. سأرسل لك رسالة بعد الحوالة.", "speaker": "Partner", "src": "../../assets/audio/unit-07/part-03-listening/016.mp3", "text": "Of course. I will send you a message after the transfer."}, {"ar": "ممتاز. شكراً جزيلاً لك.", "speaker": "Huda", "src": "../../assets/audio/unit-07/part-03-listening/017.mp3", "text": "Perfect. Thank you very much."}], "title": "Dialogue D2"}], "part-04-speaking": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-04-speaking/001.mp3", "text": "A: Say you paid ('I paid the invoice yesterday')."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-04-speaking/002.mp3", "text": "B: Check and confirm ('We received it."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-04-speaking/003.mp3", "text": "Thank you')."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-04-speaking/004.mp3", "text": "B: Say the amount ('45,000 dollars — the full amount')."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-04-speaking/005.mp3", "text": "A: Ask about your account ('Is my account clear?')."}], "title": "Read and listen"}], "part-05-reading": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/001.mp3", "text": "In business, money is more than money."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/002.mp3", "text": "It is a promise."}, {"ar": "عندما يشتري منك شريك، فإنه يعد بالدفع.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/003.mp3", "text": "When a partner buys from you, they promise to pay."}, {"ar": "عندما ترسل فاتورة، فأنت تقول: وعدت بدفع هذا، بحلول هذا اليوم.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/004.mp3", "text": "When you send an invoice, you say: 'You promised to pay this, by this day.'"}, {"ar": "وعندما يدفع الشريك في موعده، فإنه يفي بوعده.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/005.mp3", "text": "And when the partner pays on time, they keep their promise."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/006.mp3", "text": "This is why payment is not just about money."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/007.mp3", "text": "It is about trust."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/008.mp3", "text": "Think about two partners."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/009.mp3", "text": "The first partner always pays on time."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/010.mp3", "text": "Every invoice, every due date, the money arrives."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/011.mp3", "text": "You never worry."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/012.mp3", "text": "You know: this partner keeps their word."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/013.mp3", "text": "You trust them, and you want to do more business with them."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/014.mp3", "text": "The second partner pays late."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/015.mp3", "text": "Every time, you must send a reminder."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/016.mp3", "text": "Every time, you wait, and you worry."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/017.mp3", "text": "You do not trust them, and you do not want more business."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/018.mp3", "text": "The difference between them is not money."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/019.mp3", "text": "It is trust."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/020.mp3", "text": "So how do you build trust with money?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/021.mp3", "text": "It is simple."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/022.mp3", "text": "First, pay on time."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/023.mp3", "text": "When you owe money, pay it by the due date, or before."}, {"ar": "هذه أسرع طريقة لبناء اسم جيد.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/024.mp3", "text": "This is the fastest way to build a good name."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/025.mp3", "text": "Second, be clear."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/026.mp3", "text": "Send clear invoices, with the right amount and the right date."}, {"ar": "وعندما تستلم دفعة، أكّدها.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/027.mp3", "text": "And when you receive a payment, confirm it."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/028.mp3", "text": "A short message — 'Thank you, we received your payment' — tells the partner that everything is correct."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/029.mp3", "text": "Third, keep good records."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/030.mp3", "text": "Write down every payment: the amount, the date, the invoice."}, {"ar": "عندئذٍ، إذا طُرح سؤال يوماً، يكون لديك الجواب.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/031.mp3", "text": "Then, if there is ever a question, you have the answer."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/032.mp3", "text": "And here is the deepest truth."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/033.mp3", "text": "In business, your name is worth more than any single payment."}, {"ar": "إذا دفعت في الموعد، في كل مرة، سيثق بك الناس.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/034.mp3", "text": "If you pay on time, every time, people will trust you."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/035.mp3", "text": "They will give you better prices."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/036.mp3", "text": "They will wait for you when you need time."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/037.mp3", "text": "They will choose you over other companies."}, {"ar": "الاسم الجيد، المبني على الثقة، أثمن ما يمكن أن تملكه أي شركة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/038.mp3", "text": "A good name, built on trust, is the most valuable thing a business can have."}, {"ar": "ويُبنى دفعةً بعد دفعة: بهدوء، وبأمانة، وفي الموعد.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/039.mp3", "text": "And it is built one payment at a time — quietly, honestly, on time."}, {"ar": "لذلك عندما تدفع فاتورة، تذكّر: أنت لا تنقل مالاً فحسب.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/040.mp3", "text": "So when you pay an invoice, remember: you are not just moving money."}, {"ar": "أنت تفي بوعد، وتبني اسماً.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/041.mp3", "text": "You are keeping a promise, and building a name."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/042.mp3", "text": "Keep your promises, and the money will follow."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/043.mp3", "text": "Money is a (1)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/044.mp3", "text": "A partner who pays on (2)… keeps their word, and you (3)… them."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/045.mp3", "text": "To build trust: pay on time, be (4)…, and keep good (5)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-05-reading/046.mp3", "text": "Your good (6)… is worth more than any single payment."}], "title": "Read and listen"}], "part-06-writing": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-06-writing/001.mp3", "text": "Sentence starters: “We received your payment of …” · “Your invoice is now paid.” · “Your account is clear.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-06-writing/002.mp3", "text": "I said we received the payment (and the amount)."}], "title": "Read and listen"}], "part-07-trade-skills": [{"clips": [{"ar": "الفاتورة مستند بسيط لكنه مهم.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-07-trade-skills/001.mp3", "text": "An invoice is a simple but important document."}, {"ar": "تقول: اشتريت هذا، وهذا ما تدين به.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-07-trade-skills/002.mp3", "text": "It says: 'You bought this, and this is what you owe.'"}, {"ar": "الفاتورة الجيدة لها أجزاء واضحة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-07-trade-skills/003.mp3", "text": "A good invoice has clear parts."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-07-trade-skills/004.mp3", "text": "At the top: the INVOICE NUMBER, like INV-2043."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-07-trade-skills/005.mp3", "text": "Then the CUSTOMER."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-07-trade-skills/006.mp3", "text": "Then the PRODUCT, the QUANTITY, and the AMOUNT — the money to pay."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-07-trade-skills/007.mp3", "text": "And two very important parts: the DUE DATE (the day to pay by) and the STATUS (paid or unpaid)."}, {"ar": "تتفق الشركات أيضاً على شروط الدفع قبل الصفقة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-07-trade-skills/008.mp3", "text": "Companies also agree PAYMENT TERMS before a deal."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-07-trade-skills/009.mp3", "text": "Sometimes the partner pays a DEPOSIT first — for example, 30% before the goods leave."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-07-trade-skills/010.mp3", "text": "Then they pay the BALANCE — the rest — later."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-07-trade-skills/011.mp3", "text": "This protects both sides."}, {"ar": "لماذا تاريخ الاستحقاق مهم إلى هذا الحد؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-07-trade-skills/012.mp3", "text": "Why is the due date so important?"}, {"ar": "لأن الدفعة المتأخرة وعد مكسور.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-07-trade-skills/013.mp3", "text": "Because a late payment is a broken promise."}, {"ar": "عندما ترسل فاتورة، اكتب تاريخ الاستحقاق بوضوح دائماً.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-07-trade-skills/014.mp3", "text": "When you send an invoice, always write the due date clearly."}, {"ar": "وعندما تستلم دفعة، تحقق من المبلغ، وأكّدها برسالة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-07-trade-skills/015.mp3", "text": "And when you receive a payment, check the amount, and confirm it with a message."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-07-trade-skills/016.mp3", "text": "Good financial communication is simple: clear invoices, clear due dates, and a clear 'thank you' when the money arrives."}, {"ar": "أتقن هذه الأمور الصغيرة، وسيسير الجانب المالي من عملك بسلاسة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-07-trade-skills/017.mp3", "text": "Do these small things well, and the money side of your business will run smoothly."}], "title": "Read and listen"}], "part-08-consolidation": [{"clips": [{"ar": "في نهاية الشهر، تتفقّد هدى سجلّ المدفوعات.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/001.mp3", "text": "At the end of the month, Huda checks her payments record."}, {"ar": "إنه جدول بسيط، لكنه مهم جداً.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/002.mp3", "text": "It is a simple table, but it is very important."}, {"ar": "يبيّن كل فاتورة، وكل مبلغ، والحالة: مدفوعة أو غير مدفوعة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/003.mp3", "text": "It shows every invoice, every amount, and the status: paid or unpaid."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/004.mp3", "text": "Huda reads it slowly."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/005.mp3", "text": "Invoice 2041: paid."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/006.mp3", "text": "Invoice 2042: paid."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/007.mp3", "text": "Invoice 2043 — NorthBridge — paid."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/008.mp3", "text": "But invoice 2044: unpaid."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/009.mp3", "text": "Someone did not pay yet."}, {"ar": "لا تقلق هدى، لكنها لا تنسى.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/010.mp3", "text": "Huda does not worry, but she does not forget."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/011.mp3", "text": "She checks the due date for invoice 2044."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/012.mp3", "text": "It was last Friday."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/013.mp3", "text": "So the payment is a little late."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/014.mp3", "text": "Huda writes a polite message to that partner: “Dear Sir, our records show invoice 2044 is not paid yet."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/015.mp3", "text": "The due date was last Friday."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/016.mp3", "text": "Please can you check it?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/017.mp3", "text": "The message is short and polite."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/018.mp3", "text": "It is not angry."}, {"ar": "إنها تذكّر الشريك فقط، بلطف.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/019.mp3", "text": "It just reminds the partner, kindly."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/020.mp3", "text": "The next day, the partner replies: “You are right."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/021.mp3", "text": "I made the transfer this morning.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/022.mp3", "text": "Huda checks the bank."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/023.mp3", "text": "Yes — the money arrived."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/024.mp3", "text": "She marks invoice 2044 as paid."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/025.mp3", "text": "Now every invoice in the record is paid."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/026.mp3", "text": "The month is clear."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/027.mp3", "text": "Karim sees the record and smiles."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/028.mp3", "text": "“Good work, Huda."}, {"ar": "السجلّ الواضح شركة سعيدة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/029.mp3", "text": "A clear record is a happy company."}, {"ar": "تعرف تماماً من دفع، ومن لم يدفع، ومتى.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/030.mp3", "text": "You know exactly who paid, who did not, and when."}, {"ar": "عندما تحفظ سجلات جيدة، لا تخسر مالاً أبداً، ولا تفقد النوم.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-08-consolidation/031.mp3", "text": "When you keep good records, you never lose money, and you never lose sleep.”"}], "title": "Read and listen"}], "part-09-cases": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-09-cases/001.mp3", "text": "You send an invoice for 54,000 dollars."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-09-cases/002.mp3", "text": "But the correct amount is 45,000 dollars."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-09-cases/003.mp3", "text": "You wrote the numbers in the wrong order."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-09-cases/004.mp3", "text": "The partner sees the mistake."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-09-cases/005.mp3", "text": "Write one sentence to say sorry and give the correct amount."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-09-cases/006.mp3", "text": "A partner did not pay invoice 2044."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-09-cases/007.mp3", "text": "The due date was last Friday."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-09-cases/008.mp3", "text": "It is now Tuesday."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-09-cases/009.mp3", "text": "A partner paid an invoice, but nobody sent a confirmation."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-09-cases/010.mp3", "text": "The partner does not know if the money arrived."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-09-cases/011.mp3", "text": "They are worried, and they send an email to ask."}], "title": "Read and listen"}], "part-10-review": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-10-review/001.mp3", "text": "Huda sent the invoice two weeks ago."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-10-review/002.mp3", "text": "The amount was 45,000 dollars, and the due date was the first of May."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-10-review/003.mp3", "text": "Ms. Chen paid by bank transfer yesterday."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-10-review/004.mp3", "text": "Huda received the money this morning and marked the invoice as paid."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-10-review/005.mp3", "text": "The account is now clear."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-10-review/006.mp3", "text": "[Teacher reads] 'Thank you."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-10-review/007.mp3", "text": "We received your payment of 45,000 dollars yesterday, by bank transfer."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-10-review/008.mp3", "text": "Your invoice is now paid, and your account is clear.'"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-10-review/009.mp3", "text": "I can talk about the past (a payment, a deal)."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-10-review/010.mp3", "text": "I can write a payment-confirmation email."}], "title": "Read and listen"}], "part-11-foundations": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/001.mp3", "text": "This unit is about invoices and payments."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/002.mp3", "text": "But it points to one of the oldest ideas in all of business: your word is your worth."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/003.mp3", "text": "In money, and in life, the person who keeps their promises is the person everyone trusts."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/004.mp3", "text": "And trust, in the end, is worth more than money."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/005.mp3", "text": "Think about what really happens when a partner pays on time."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/006.mp3", "text": "Yes, the money arrives."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/007.mp3", "text": "But something bigger happens too."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/008.mp3", "text": "The partner shows you who they are."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/009.mp3", "text": "They say, without words: 'I keep my promises."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/010.mp3", "text": "You can trust me.'"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/011.mp3", "text": "And every time they do this, the trust grows a little more."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/012.mp3", "text": "After ten deals, all paid on time, you trust that partner completely."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/013.mp3", "text": "You do not check."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/014.mp3", "text": "You do not worry."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/015.mp3", "text": "You just work."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/016.mp3", "text": "This is a wonderful thing in business — and it is built only on kept promises."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/017.mp3", "text": "Now think about the opposite."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/018.mp3", "text": "A partner pays late, again and again."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/019.mp3", "text": "Each late payment is a small broken promise."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/020.mp3", "text": "And broken promises break trust — slowly at first, then completely."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/021.mp3", "text": "In the end, you do not want to work with that partner, even if their price is good."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/022.mp3", "text": "Because in business, you are not just buying a product."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/023.mp3", "text": "You are trusting a person."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/024.mp3", "text": "And a person you cannot trust is not worth the trouble, at any price."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/025.mp3", "text": "So here is the lesson, for money and for life: keep your promises, especially the small ones."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/026.mp3", "text": "Pay on time."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/027.mp3", "text": "Do what you say."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/028.mp3", "text": "Arrive when you say you will."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/029.mp3", "text": "These small, kept promises are the bricks of trust."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/030.mp3", "text": "And trust is the foundation of everything good, in business and in life."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/031.mp3", "text": "Your word is a kind of money."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/032.mp3", "text": "If you always keep it, you become rich in the way that matters most: people believe you."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/033.mp3", "text": "And when people believe you, every door opens."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/034.mp3", "text": "So guard your word carefully."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/035.mp3", "text": "It is the most valuable thing you own."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/036.mp3", "text": "Think of a person you trust completely."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/037.mp3", "text": "Why do you trust them?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/038.mp3", "text": "Do they keep their promises?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/039.mp3", "text": "Tell your partner one small promise that a person kept, and how it made you trust them."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/040.mp3", "text": "Write a few sentences (30–50 words) about a past deal or payment."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/041.mp3", "text": "Use the past simple and a time expression."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/042.mp3", "text": "For example: 'Last month, we sent an invoice."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/part-11-foundations/043.mp3", "text": "The partner paid on time…'"}], "title": "Read and listen"}], "warm-up": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/001.mp3", "text": "Look at the pictures."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/002.mp3", "text": "Answer these questions before you read."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/003.mp3", "text": "The goods arrived at NorthBridge's port."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/004.mp3", "text": "The order is complete."}, {"ar": "الآن حان وقت الخطوة الأخيرة: الدفع.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/005.mp3", "text": "Now it is time for the last step: the payment."}, {"ar": "هذا عمل الفريق المالي.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/006.mp3", "text": "This is the work of the finance team."}, {"ar": "هدى المحاسِبة، ولينا المديرة المالية، تقومان بهذا العمل.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/007.mp3", "text": "Huda, the Accountant, and Lina, the Financial Manager, do this work."}, {"ar": "ترسل هدى الفاتورة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/008.mp3", "text": "Huda sends the invoice."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/009.mp3", "text": "An invoice is a document that says: “You bought this."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/010.mp3", "text": "This is the amount."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/011.mp3", "text": "Please pay by this date.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/012.mp3", "text": "Huda's invoice says: cement, 1,000 tonnes, 45,000 dollars."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/013.mp3", "text": "The due date is the first of May."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/014.mp3", "text": "She sends it to Ms. Chen by email."}, {"ar": "تسأل لينا: متى أرسلتِ الفاتورة؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/015.mp3", "text": "“When did you send the invoice?” asks Lina."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/016.mp3", "text": "“I sent it yesterday,” says Huda."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/017.mp3", "text": "“The due date is the first of May."}, {"ar": "هذا يمنح السيدة تشِن أسبوعين للدفع.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/018.mp3", "text": "That gives Ms. Chen two weeks to pay.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/019.mp3", "text": "Two days later, good news arrives."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/020.mp3", "text": "Ms. Chen paid the invoice."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/021.mp3", "text": "She made a bank transfer of 45,000 dollars."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/022.mp3", "text": "Huda checks the bank."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/023.mp3", "text": "Yes — the money arrived this morning."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/024.mp3", "text": "“She paid on time,” says Huda, happy."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/025.mp3", "text": "“A good partner always pays on time.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/026.mp3", "text": "Huda records the payment."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/027.mp3", "text": "She writes it in the payments record: invoice PO-1243, 45,000 dollars, paid, second of May."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/028.mp3", "text": "Now the account is clear."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/029.mp3", "text": "NorthBridge owes nothing."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/030.mp3", "text": "Huda writes a short email to Ms. Chen: “Dear Ms. Chen, thank you."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/031.mp3", "text": "We received your payment of 45,000 dollars yesterday."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/032.mp3", "text": "Your invoice is now paid, and your account is clear."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/033.mp3", "text": "Best regards, Huda.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/034.mp3", "text": "“Good,” says Karim."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/035.mp3", "text": "“The order is finished, and the money is in the bank."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/036.mp3", "text": "This is a good, complete deal."}, {"ar": "صنعنا إسمنتاً جيداً، وشحنّاه بأمان، ودفعت نورث بريدج في موعدها.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/037.mp3", "text": "We made good cement, we shipped it safely, and NorthBridge paid on time."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/038.mp3", "text": "Both sides kept their word."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-07/warm-up/039.mp3", "text": "That is how trust grows — one deal at a time.”"}], "title": "Read and listen"}]}, "unit": 7});
